def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]):
        """
        Convert the SQL query to use the out-style parameters instead of
        the in-style parameters.

        :param sql: The SQL query.
        :type sql: :class:`str` or :class:`bytes`
        :param params: The set of in-style parameters.
        :type params: :class:`collections.abc.Mapping` or :class:`collections.abc.Sequence`
        :return: A tuple containing the formatted SQL query and the converted out-style parameters.
        :rtype: :class:`tuple`
        """

        if isinstance(params, dict):
            out_params = {}
            for key, value in params.items():
                out_params[f"p_{key}"] = value
        else:
            out_params = []
            for value in params:
                out_params.append(value)

        return sql % out_params, out_params

