def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("Prior must be an InventoryValidator object")

    # Check that the prior inventory is a prior version of the current inventory
    if self.get_version() <= prior.get_version():
        raise ValueError("Prior inventory must be an earlier version than the current inventory")

    # Check that the prior inventory is consistent with the current inventory
    if not self.is_consistent_with(prior):
        raise ValueError("Prior inventory is not consistent with the current inventory")

    # Check that the prior inventory has all the required information
    if not prior.has_required_information():
        raise ValueError("Prior inventory does not have all the required information")

    # Check that the prior inventory has no conflicting information
    if prior.has_conflicting_information():
        raise ValueError("Prior inventory has conflicting information")

    # Check that the prior inventory meets the inventory validation criteria
    if not prior.meets_validation_criteria():
        raise ValueError("Prior inventory does not meet the inventory validation criteria")

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if not isinstance(prior, InventoryValidator):
            raise TypeError("prior is not an InventoryValidator")

        # Check version numbers
        if prior.version != self.version - 1:
            raise InventoryValidationError("prior version number is not one less than current version number")

        # Check that prior inventory is a subset of current inventory
        if not set(prior.inventory.keys()).issubset(set(self.inventory.keys())):
            raise InventoryValidationError("prior inventory is not a subset of current inventory")

        # Check that all items in prior inventory have smaller or equal quantities
        for key, value in prior.inventory.items():
            if self.inventory[key] < value:
                raise InventoryValidationError("item in prior inventory has greater quantity than in current inventory")

        # Check that all items in current inventory have non-negative quantities
        for key, value in self.inventory.items():
            if value < 0:
                raise InventoryValidationError("item in current inventory has negative quantity")

