def validate_fixity(self, fixity, manifest_files):
   """Validate fixity block in inventory.

   Check the structure of the fixity block and makes sure that only files
   listed in the manifest are referenced.
   """
   # validate structure
   if not isinstance(fixity, dict):
      raise ValueError("Fixity must be a dictionary")
   if not fixity:
      raise ValueError("Fixity must not be empty")
   for algorithm, values in fixity.items():
      if not isinstance(algorithm, str):
         raise ValueError("Algorithm must be a string")
      if not algorithm:
         raise ValueError("Algorithm must not be empty")
      if not isinstance(values, (list, tuple)):
         raise ValueError("Values must be a list or a tuple")
      for value in values:
         if not isinstance(value, str):
            raise ValueError("Value must be a string")
         if not value:
            raise ValueError("Value must not be empty")
   # validate files
   for file, fixity in fixity.items():
      if file not in manifest_files:
         raise ValueError(f"File {file} is not in the manifest")
      if fixity["algorithm"] != manifest_files[file]["fixity"]["algorithm"]:
         raise ValueError(f"Fixity algorithm {fixity['algorithm']} for file {file} does not match the algorithm in the manifest {manifest_files[file]['fixity']['algorithm']}")
      if fixity["value"] != manifest_files[file]["fixity"]["value"]:
         raise ValueError(f"Fixity value {fixity['value']} for file {file} does not match the value in the manifest {manifest_files[file]['fixity']['value']}")
