def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    packages = {}
    for f in os.listdir(folder):
        if not f.endswith('.xml'):
            continue
        basename = os.path.basename(f)
        package = packages.setdefault(basename, {})
        with open(os.path.join(folder, f), 'r') as xml_file:
            tree = ET.parse(xml_file)
            root = tree.getroot()
            for child in root:
                if child.tag == 'package':
                    package[child.attrib['name']] = {}
                    for sub_child in child:
                        if sub_child.tag == 'version':
                            package[child.attrib['name']]['version'] = sub_child.text
                        elif sub_child.tag == 'url':
                            package[child.attrib['name']]['url'] = sub_child.text
                        elif sub_child.tag == 'description':
                            package[child.attrib['name']]['description'] = sub_child.text
    return packages

