def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    output = []
    for i, arg in enumerate(args):
        if isinstance(arg, BinaryExpression) and arg.op in ("&", "|"):
            if arg.op == "&":
                if arg.left == arg.right:
                    output.append(arg.left)
                else:
                    output.append(arg)
            elif arg.op == "|":
                if arg.left == ~arg.right:
                    output.append(arg.left)
                else:
                    output.append(arg)
        else:
            output.append(arg)
    return output

