def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # We require at least one version directory.
    if len(version_dirs) == 0:
        raise RuntimeError("No version directories found.")

    # Make sure the directory names are valid version strings.
    for dir in version_dirs:
        try:
            int(dir)
        except ValueError:
            raise RuntimeError(f"Invalid version directory name: {dir}")

    # Record the previous inventory.
    prev_inventory = None

    # Iterate through the versions and validate the inventories.
    for i, dir in enumerate(version_dirs):
        # Load the current inventory.
        inventory_path = os.path.join(dir, "inventory")
        if os.path.exists(inventory_path):
            with open(inventory_path) as f:
                inventory = json.load(f)
        else:
            raise RuntimeError(f"No inventory file found in version directory {dir}")

        # Make sure the inventory is valid.
        try:
            validate_inventory(inventory)
        except ValueError as e:
            raise RuntimeError(f"Invalid inventory in version directory {dir}: {e}")

        # Check if the inventory has the same content as the previous one.
        if prev_inventory is not None:
            for digest in inventory["root"]["content"]:
                if digest not in prev_inventory["root"]["content"]:
                    raise RuntimeError(f"Digest {digest} found in version directory {dir} missing from previous inventory")

