def vertex3tuple(vertices):
    """return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    try:
        vertices = tuple(vertices)
        if len(vertices) < 3:
            raise ValueError("At least 3 vertices are required to form a polygon.")
        vertices_len = len(vertices)
        output = []
        for i in range(len(vertices)):
            if i == vertices_len - 1:
                output.append((vertices[i], vertices[0], vertices[1]))
            else:
                output.append((vertices[i], vertices[i+1], vertices[(i+2) % vertices_len]))
        return output
    except ValueError as e:
        print(e)
    except IndexError as e:
        print(e)

