def subprocess_run_helper(func, *args, timeout=None, extra_env=None):
    """
    Run a function in a sub-process.

    Parameters
    ----------
    func : function
        The function to be run.  It must be in a module that is importable.
    *args : str
        Any additional command line arguments to be passed in
        the first argument to ``subprocess.run``.
    extra_env : dict[str, str]
        Any additional environment variables to be set for the subprocess.
    """
    if not callable(func):
        raise TypeError("The first argument must be a callable function.")
    if timeout is not None:
        if not isinstance(timeout, (float, int)):
            raise TypeError("The timeout argument must be a number.")
        if timeout <= 0:
            raise ValueError("The timeout argument must be positive.")
    if extra_env is not None:
        if not isinstance(extra_env, dict):
            raise TypeError("The extra_env argument must be a dictionary.")
        for key, value in extra_env.items():
            if not isinstance(key, str):
                raise TypeError("The keys in the extra_env dictionary must be strings.")
            elif not isinstance(value, str):
                raise TypeError("The values in the extra_env dictionary must be strings.")

    process = subprocess.Popen(['python', '-c', func.__module__, *args])
    try:
        process.wait(timeout=timeout)
    except subprocess.TimeoutExpired:
        process.kill()
    except:
        process.kill()
        raise
    finally:
        process.wait()
        if process.returncode != 0:
            return process.returncode
        else:
            return None

