def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if not hist:
        raise ValueError("The histogram must contain at least one bin")

    # Determine the graph scale
    if scale is None:
        scale = hist.scale
    elif scale is True:
        scale = hist.scale or None

    # Determine the coordinates of the graph points
    if get_coordinate == "left":
        coordinates_func = lambda bin_: bin_.left
    elif get_coordinate == "right":
        coordinates_func = lambda bin_: bin_.right
    elif get_coordinate == "middle":
        coordinates_func = lambda bin_: (bin_.left + bin_.right) / 2
    else:
        raise ValueError("Unknown coordinate type: {}".format(get_coordinate))

    # Create the graph
    x = []
    y = []
    for bin_ in hist:
        x.append(coordinates_func(bin_))
        if make_value is None:
            y.append(bin_.value)
        else:
            y.append(make_value(bin_))

    graph = Graph(x, y, scale=scale, field_names=field_names)
    return graph

