    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # if an explicit metaclass is specified, use it
    if explicit_mc is not None:
        return explicit_mc

    # if we have multiple bases with different metaclasses, raise an error
    if len(bases) > 1:
        metaclasses = {b.__class__ for b in bases}
        if len(metaclasses) > 1:
            raise TypeError("Incompatible metaclasses", metaclasses)

    # if we have a single base with a metaclass, use it
    if len(bases) == 1:
        return bases[0].__class__

    # if we have multiple bases with the same metaclass, use it
    if len(bases) > 1:
        metaclass = bases[0].__class__
        if all(b.__class__ is metaclass for b in bases):
