def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit `__metaclass__`

    Raises:
        TypeError: if no suitable metaclass can be determined

    Returns:
        type: the determined metaclass
    """

    # Explicit metaclass takes precedence
    if explicit_mc:
        return explicit_mc

    # Otherwise, try to determine one based on the bases
    metaclasses = set(type(base) for base in bases)
    if metaclasses == set([type]):
