def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Make sure the cache is not empty
    if not self.dict.size:
        raise KeyError("popitem(): dictionary is empty")

    # Find the key with the oldest access time
    oldest = None
    for key, value in self.dict.items():
        if oldest is None or value.access_time < oldest.access_time:
            oldest = value

    # Remove the oldest item from the dictionary and return it
    self.dict.pop(oldest, None)
    return (oldest.key, oldest.value)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    for key, (value, count) in self.items():
        if count == self.min_count:
            del self[key]
            return key, value
    raise ValueError("popitem(): unable to find the least frequently used item")

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    for key, (value, count) in list(self.items()):
        if count < min_count:
            min_count = count
            min_key = key
    del self[min_key]
    return (min_key, value)

