def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not url:
        raise ValueError("url cannot be empty")

    if document_path and not isinstance(document_path, str):
        raise ValueError("document_path must be a string")

    base_url = url
    if not base_url.endswith("/"):
        base_url += "/"

    nodeinfo_url = base_url
    if document_path:
        nodeinfo_url += document_path
    else:
        nodeinfo_url += ".well-known/nodeinfo"

    response = requests.get(nodeinfo_url)
    if response.status_code != 200:
        raise Exception(f"Failed to retrieve NodeInfo document from {url}")

    try:
        nodeinfo_document = response.json()
    except JSONDecodeError:
        raise Exception(f"Invalid NodeInfo document returned from {url}")

    return nodeinfo_document

