def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try to parse the document as JSON
        json_data = json.loads(document)
        # If the document is valid JSON, it's in the new format
        link = json_data["links"][0]
        return {
            "subject": link["href"],
            "aliases": [alias["href"] for alias in link["hrefs"]],
            "properties": json_data["properties"],
        }
    except ValueError:
        # If the document is not valid JSON, it's in the old XRD format
        xrd_data = ElementTree.fromstring(document)
        # Find the <Subject> element
        subject_element = xrd_data.find(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject")
        if subject_element is None:
            raise ValueError("Subject element not found in XRD document")
        subject = subject_element.text
        # Find all the <Link> elements
        link_elements = xrd_data.findall(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link")
        aliases = []
        properties = {}
        for link_element in link_elements:
            type_attr = link_element.attrib["type"]
            if type_attr == "http://schemas.xmlsoap.org/ws/2005/04/discovery":
                # This is a Diaspora-specific link, parse the properties
                properties = {p.attrib["name"]: p.attrib["value"] for p in link_element.findall(".//{http://schemas.xmlsoap.org/ws/2005/04/discovery}Property")}
            elif type_attr == "http://schemas.xmlsoap.org/aws/2005/04/discovery":
                # This is an Amazon Web Services-specific link, ignore for now
                pass
            else:
                # This is another type of link, add it to the list of aliases
                href = link_element.attrib["href"]
                aliases.append(href)
        return {
            "subject": subject,
            "aliases": aliases,
            "properties": properties,
        }

