def _get_conditionally_required_args(self, command_name, options_spec, args):
    required_args = []
    for option in options_spec:
        if 'required_when' in option and option['required_when'] is not None:
            condition = option['required_when']
            if isinstance(condition, str):
                condition = condition.split('=')
                if len(condition) != 2:
                    raise ValueError(f"Invalid format for 'required_when' condition '{condition}'")
                required_arg = condition[0]
                required_value = condition[1]
                if required_arg not in args:
                    continue
                if args[required_arg] == required_value:
                    required_args.append(option['name'])
            elif isinstance(condition, (tuple, list)):
                for item in condition:
                    if len(item) != 2:
                        raise ValueError(f"Invalid format for 'required_when' condition '{condition}'")
                    required_arg = item[0]
                    required_value = item[1]
                    if required_arg not in args:
                        continue
                    if args[required_arg] == required_value:
                        required_args.append(option['name'])
            else:
                raise ValueError(f"Invalid format for 'required_when' condition '{condition}'")
    return required_args

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required_args = []
    for opt in options_spec:
        if opt.get("required_when"):
            condition = opt["required_when"]
            if isinstance(condition, str):
                condition = {condition: True}
            if all(args.get(k) == v for k, v in condition.items()) and opt["name"] not in args:
                required_args.append(opt["name"])
    return required_args

